userscript.function:

			var clientDesignObj = <%=new Gson().toJson(pageData)%>;
            var indexObj = $var.module = new SepoaIndex({
                cont:mainFrame,
                mode:Sepoa.request.login || "login",
                form:clientDesignObj.LOGIN_DESIGN_TYPE || "default",
                style:clientDesignObj,
                service:Sepoa.request.service || "login",
                isPopup:(Sepoa.request.isPopup == 'true'),
                sendParams:(Sepoa.params)?Sepoa.params.params:null,
            });

            indexObj.attachEvent("onLoginAfter", onLoginAfter);

            indexObj.attachEvent("onLoginEnd", function(flag){
                if(flag){
                    if(Sepoa.request.isPopup != 'true'){
                        location.href = window.CONTEXT_NAME + "/Main.sux";
                    }else{
                        selfObj.close();
                    }
                }
            });


var result = false;
switch(so.status){
case "1":
    share.message = sUtils.cache.text.get("LOGIN.STATUS_"+so.status);
    result = true;
    break;
case "100016":
    if(so.param.TYPE == 'POPUP'){
        sUtils.popup.modal({
            url:window.CONTEXT_NAME+so.param.URL,
            params:so.param,
            title:so.param.TITLE
        });
    }else{
        share.message = sUtils.cache.text.get("LOGIN.STATUS_"+so.status);
    }
    break;
case "100011":
case "100012":
case "100013":
case "100014":
case "100017":
	const pwElem = document.querySelector('.sepoa-index-module-target.sepoa-index-module-type-login_input.sepoa-index-login-input#password');

	pwElem.value = '';
	pwElem.blur();

    const popup = sUtils.popup.modal({
        url:window.CONTEXT_NAME+"/Admin/UpdateUserInfo/AdminUpdateUserInfoPassWord.sux",
        params:{
            USER_ID: so.param.userId
        },
        width:200,
        height:400,
        title:sUtils.cache.text.get("LOGIN.STATUS_" + so.status)
    });

    popup[popup.name].button('minmax').hide();
    break;
default:
    share.message = sUtils.cache.text.get("LOGIN.STATUS_"+so.status);
}

if(result && Sepoa.params && Sepoa.params.callback){
    return Sepoa.params.callback(so, share);
}
return result;
